'use client';

import React, { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { faCopy, faMicrophone, faMicrophoneSlash, faVideo, faVideoSlash, faArrowLeft } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { db } from '@/lib/firebase';
import { addDoc, collection, serverTimestamp, query, getDocs } from 'firebase/firestore';
import { v4 as uuidv4 } from 'uuid';

interface RoomPageProps {
  onRoomCreated: (roomId: string) => void;
}

export default function RoomPage({ onRoomCreated }: RoomPageProps) {
  const router = useRouter();
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const privateFieldsRef = useRef<HTMLDivElement>(null);

  const [visibility, setVisibility] = useState<'public' | 'private'>('public');
  const [participantEmails, setParticipantEmails] = useState<string[]>(['']);
  const [limit, setLimit] = useState<number | null>(null);
  const [roomLink, setRoomLink] = useState<string | null>(null);
  const [roomName, setRoomName] = useState('');
  const [objective, setObjective] = useState('');
  const [micOn, setMicOn] = useState(true);
  const [cameraOn, setCameraOn] = useState(true);
  const [existingRooms, setExistingRooms] = useState<any[]>([]);
  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pastedLink, setPastedLink] = useState('');
  const [userId, setUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getSessionInfo = async () => {
      try {
        const res = await fetch('/api/session');
        const data = await res.json();
        console.log("✅ Session user:", data);

        if (data.user?.id) {
          setUserId(data.user.id.toString());
        } else {
          console.error("❌ user.id is missing from session");
          setError("Session is invalid");
        }
      } catch (err) {
        console.error("❌ Failed to fetch session", err);
        setError("Could not fetch session");
      } finally {
        setLoading(false);
      }
    };
    getSessionInfo();
  }, []);

  useEffect(() => {
    if (!roomName) {
      setRoomLink(null);
      return;
    }
    const generateRandomRoomName = (): string => {
      const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
      let result = '';
      for (let i = 0; i < 5; i++) {
        const randomIndex = Math.floor(Math.random() * characters.length);
        result += characters[randomIndex];
      }
      return result;
    };
    const randomName = generateRandomRoomName();
    const tempRoomId = `${roomName.toLowerCase().replace(/\s+/g, '-')}-${randomName}`;
    const tempLink = `${window.location.origin}/join/${tempRoomId}`;
    setRoomLink(tempLink);
  }, [roomName]);

  useEffect(() => {
    const manageStream = async () => {
      if (!micOn && !cameraOn) {
        if (streamRef.current) {
          streamRef.current.getTracks().forEach(track => track.stop());
          streamRef.current = null;
          if (videoRef.current) videoRef.current.srcObject = null;
        }
        return;
      }

      try {
        const constraints = {
          video: cameraOn,
          audio: micOn
        };

        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        
        if (streamRef.current) {
          streamRef.current.getTracks().forEach(track => track.stop());
        }

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (e) {
        console.error('Could not get media', e);
        setError('Failed to access camera/microphone. Please check permissions.');
        setMicOn(prev => !prev);
        setCameraOn(prev => !prev);
      }
    };

    manageStream();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [micOn, cameraOn]);

  useEffect(() => {
    const fetchRooms = async () => {
      if (!userId) return;
      const q = query(collection(db, 'rooms'));
      const querySnapshot = await getDocs(q);
      const rooms: any[] = [];
      querySnapshot.forEach((doc) => {
        const data = doc.data();
        if (data.userId === userId) {
          rooms.push({ id: doc.id, name: data.name });
        }
      });
      setExistingRooms(rooms);
    };
    fetchRooms();
  }, [userId]);

  const toggleMic = async (event: React.MouseEvent<HTMLButtonElement>): Promise<void> => {
    event.preventDefault();
    try {
      const newMicState = !micOn;
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = newMicState;
        });
      }
      setMicOn(newMicState);
    } catch (err) {
      console.error("Error toggling microphone:", err);
      setError("Could not toggle microphone");
    }
  };

  const toggleCamera = async (event: React.MouseEvent<HTMLButtonElement>): Promise<void> => {
    event.preventDefault();
    try {
      const newCameraState = !cameraOn;
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.enabled = newCameraState;
        });
      }
      setCameraOn(newCameraState);
    } catch (err) {
      console.error("Error toggling camera:", err);
      setError("Could not toggle camera");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!userId) {
      setError("Please wait for session to load.");
      return;
    }

    if (!roomName || !objective) {
      setError('Room name and objective are required.');
      return;
    }

    const roomId = `${roomName.toLowerCase().replace(/\s+/g, '-')}-${uuidv4().substring(0, 5)}`;

    try {
      await addDoc(collection(db, 'rooms'), {
        id: roomId,
        name: roomName,
        limit: limit || null,
        objective,
        visibility,
        participantEmails: participantEmails.map((email) => email.trim()),
        micStatus: micOn ? 'on' : 'off',
        cameraStatus: cameraOn ? 'on' : 'off',
        userId,
        createdAt: serverTimestamp(),
      });

      setRoomLink(`${window.location.origin}/join/${roomId}`);
      onRoomCreated(roomId);
      router.push(`/coworking/${roomId}?mic=${micOn ? 'on' : 'off'}&camera=${cameraOn ? 'on' : 'off'}`);
    } catch (error) {
      console.error('Error creating room:', error);
      setError('Failed to create room, please try again.');
    }
  };

  const handleJoinRoom = () => {
    const roomIdFromLink = pastedLink?.split('/join/')[1];
    const finalRoomId = roomIdFromLink || selectedRoomId;
    if (finalRoomId) {
      router.push(`/coworking/${finalRoomId}?mic=${micOn ? 'on' : 'off'}&camera=${cameraOn ? 'on' : 'off'}`);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-100">
        <div className="text-center p-6 bg-white rounded-lg shadow-md">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading session...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <button
          onClick={() => router.push('/profile')}
          className="flex items-center text-blue-600 hover:text-blue-800 mb-4 md:mb-6"
        >
          <FontAwesomeIcon icon={faArrowLeft} className="mr-2" />
          Back to Profile
        </button>

        <div className="flex flex-col lg:flex-row gap-6 h-[calc(100vh-150px)]">
          <div className="flex-1 bg-white rounded-xl shadow-md overflow-hidden h-full flex flex-col">
            <div className="relative flex-1 bg-gray-200">
              <video
                ref={videoRef}
                autoPlay
                muted
                playsInline
                className="absolute inset-0 w-full h-full object-cover"
              />
              {!cameraOn && (
                <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-70 text-white">
                  Camera is off
                </div>
              )}
            </div>
            <div className="flex justify-center space-x-4 p-4 bg-gray-50">
              <button
                onClick={toggleMic}
                className={`p-3 rounded-full ${micOn ? 'bg-green-500 hover:bg-green-600' : 'bg-red-500 hover:bg-red-600'} text-white transition-colors`}
                aria-label={micOn ? "Mute microphone" : "Unmute microphone"}
              >
                <FontAwesomeIcon icon={micOn ? faMicrophone : faMicrophoneSlash} />
              </button>
              <button
                onClick={toggleCamera}
                className={`p-3 rounded-full ${cameraOn ? 'bg-green-500 hover:bg-green-600' : 'bg-red-500 hover:bg-red-600'} text-white transition-colors`}
                aria-label={cameraOn ? "Turn off camera" : "Turn on camera"}
              >
                <FontAwesomeIcon icon={cameraOn ? faVideo : faVideoSlash} />
              </button>
            </div>
          </div>

          <div className="flex-1 flex flex-col h-full overflow-hidden">
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
              <h2 className="text-xl font-bold text-gray-800 mb-4">Join an Existing Room</h2>
              <div className="mb-4">
                <div className="flex mb-4 gap-2">
                  <select
                    value={selectedRoomId || ''}
                    onChange={(e) => setSelectedRoomId(e.target.value)}
                    className="flex-1/2 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  >
                    <option value="">Select an existing Room</option>
                    {existingRooms.map((room) => (
                      <option key={room.id} value={room.id}>
                        {room.name}
                      </option>
                    ))}
                  </select>
                  
                  <div className="relative">
                    <input
                      type="text"
                      placeholder="Or paste a room link"
                      value={pastedLink}
                      onChange={(e) => setPastedLink(e.target.value)}
                      className="flex-1/2 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                  </div>
                </div>
               
                <button
                  onClick={handleJoinRoom}
                  disabled={!selectedRoomId && !pastedLink}
                  className={`w-full py-3 px-4 rounded-lg font-medium transition-colors ${
                    !selectedRoomId && !pastedLink
                      ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                      : 'bg-blue-600 hover:bg-blue-700 text-white'
                  }`}
                >
                  Join Room
                </button>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-md p-6 flex-1 overflow-y-auto">
              <h2 className="text-xl font-bold text-gray-800 mb-4">Create a New Room</h2>
              
              {error && (
                <div className="mb-4 p-3 bg-red-100 border-l-4 border-red-500 text-red-700 rounded">
                  <p>{error}</p>
                </div>
              )}
              
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className='flex gap-4'>
                  <div className="w-full">
                    <label htmlFor="roomName" className="block text-sm font-medium text-gray-700 mb-1">
                      Room Name
                    </label>
                    <input
                      id="roomName"
                      type="text"
                      placeholder="e.g. Study Session, Team Meeting"
                      value={roomName}
                      onChange={(e) => setRoomName(e.target.value)}
                      required
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                  </div>
                  
                  <div className="w-full">
                    <label htmlFor="objective" className="block text-sm font-medium text-gray-700 mb-1">
                      Objective
                    </label>
                    <input
                      id="objective"
                      type="text"
                      placeholder="e.g. Study Calculus, Project Planning"
                      value={objective}
                      onChange={(e) => setObjective(e.target.value)}
                      required
                      className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                  </div>
                </div>
                
                <div>
                  <label htmlFor="visibility" className="block text-sm font-medium text-gray-700 mb-1">
                    Visibility
                  </label>
                  <select
                    id="visibility"
                    value={visibility}
                    onChange={(e) => setVisibility(e.target.value as 'public' | 'private')}
                    className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  >
                    <option value="public">Public (Anyone can join)</option>
                    <option value="private">Private (Invite only)</option>
                  </select>
                </div>

                <div 
                  ref={privateFieldsRef}
                  className={`transition-all duration-300 overflow-hidden ${
                    visibility === 'private' ? 'max-h-[500px] overflow-y-auto' : 'max-h-0'
                  }`}
                >
                  {visibility === 'private' && (
                    <>
                      <div className="pt-4">
                        <label htmlFor="limit" className="block text-sm font-medium text-gray-700 mb-1">
                          Participant Limit (optional)
                        </label>
                        <input
                          id="limit"
                          type="number"
                          placeholder="Leave empty for no limit"
                          value={limit || ''}
                          onChange={(e) => setLimit(Number(e.target.value))}
                          min="1"
                          className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                        />
                      </div>
                      
                      <div className="pt-4">
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Invite Participants
                        </label>
                        <div className="space-y-2">
                          {participantEmails.map((email, index) => (
                            <div key={index} className="flex items-center gap-2">
                              <input
                                type="email"
                                placeholder={`participant${index + 1}@example.com`}
                                value={email}
                                onChange={(e) => {
                                  const newEmails = [...participantEmails];
                                  newEmails[index] = e.target.value;
                                  setParticipantEmails(newEmails);
                                }}
                                className="flex-1 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                                required={visibility === 'private'}
                              />
                              {participantEmails.length > 1 && (
                                <button
                                  type="button"
                                  onClick={() =>
                                    setParticipantEmails(participantEmails.filter((_, i) => i !== index))
                                  }
                                  className="p-3 text-red-500 hover:text-red-700 rounded-lg"
                                  aria-label="Remove participant"
                                >
                                  &times;
                                </button>
                              )}
                            </div>
                          ))}
                          <button
                            type="button"
                            onClick={() => setParticipantEmails([...participantEmails, ''])}
                            className="text-blue-600 hover:text-blue-800 text-sm flex items-center mt-1"
                          >
                            <span className="text-lg mr-1">+</span> Add another participant
                          </button>
                        </div>
                      </div>
                    </>
                  )}
                </div>

                {roomLink && (
                  <div className="bg-gray-50 p-3 rounded-lg border border-gray-200">
                    <div className="flex items-center gap-2">
                      <input
                        type="text"
                        value={roomLink}
                        readOnly
                        className="flex-1 p-2 bg-white border border-gray-300 rounded text-sm truncate"
                      />
                      <button
                        type="button"
                        onClick={() => {
                          navigator.clipboard.writeText(roomLink);
                          alert('Link copied to clipboard!');
                        }}
                        className="p-2 bg-blue-600 hover:bg-blue-700 text-white rounded"
                        aria-label="Copy room link"
                      >
                        <FontAwesomeIcon icon={faCopy} />
                      </button>
                    </div>
                  </div>
                )}

                <button
                  type="submit"
                  disabled={!userId}
                  className={`w-full py-3 px-4 rounded-lg font-medium text-white transition-colors ${
                    !userId
                      ? 'bg-gray-400 cursor-not-allowed'
                      : 'bg-gradient-to-r from-blue-600 to-blue-800 hover:from-blue-700 hover:to-blue-900'
                  }`}
                >
                  Create Room
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}